  VALUES
    ('water.meter_reading_check', 'water', 'reduzir desperdício de água por leitura de consumo', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','control_level','time_limit','baseline','reason']::text[], 'water_meter_reading_check', 'Leitura rápida do hidrômetro', 'Hoje, verifique o hidrômetro ou indicador de consumo disponível e anote um sinal de uso anormal para investigar com segurança.', 'Transforma economia de água em observação concreta, sem exigir compra ou mudança fora do controle do usuário.', 4, 5, 'baseline'),
    ('water.hot_water_wait_reuse', 'water', 'reutilizar água limpa que seria desperdiçada', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','deficit']::text[], ARRAY['routine_moment','available_space','control_level','time_limit','reason']::text[], 'water_hot_water_wait_reuse', 'Água de espera reaproveitada', 'Hoje, observe uma espera por água quente ou corrente e teste separar a água limpa inicial para uma utilidade segura.', 'Aproveita uma perda comum e visível de água sem comprometer higiene ou conforto.', 4, 5, 'reuse'),
    ('water.cleaning_water_sequence', 'water', 'diminuir uso de água em limpeza doméstica', 3, 3, 'free', 10, 25, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','control_level','time_limit','reason']::text[], 'water_cleaning_sequence', 'Sequência de limpeza com menos água', 'Hoje, escolha uma limpeza pequena e organize a sequência para usar menos enxágues, começando pela área mais limpa.', 'Reduz água ao melhorar ordem e método, não por restrição abstrata.', 4, 5, 'method'),
    ('water.plant_watering_window', 'water', 'evitar desperdício de água em plantas ou área externa', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','weather_condition','control_level','time_limit','reason']::text[], 'water_plant_watering_window', 'Janela de rega consciente', 'Hoje, revise uma planta ou área externa e defina um horário de rega com menor evaporação, apenas se houver segurança e necessidade real.', 'Ajusta uma rotina de água a clima e necessidade, evitando desperdício invisível.', 4, 5, 'timing'),
    ('water.laundry_protocol_review', 'water', 'economizar água em rotina de lavagem de roupas', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','control_level','time_limit','comfort_level','reason']::text[], 'water_laundry_protocol_review', 'Protocolo de lavagem cheia', 'Hoje, revise uma lavagem futura e defina o critério de carga cheia, peça delicada ou reuso seguro antes de ligar a máquina.', 'Cria critério de decisão para água em vez de depender de lembrança momentânea.', 7, 7, 'protocol'),
    ('water.dishwashing_flow_protocol', 'water', 'reduzir água corrente na lavagem de louça', 4, 4, 'free', 20, 35, ARRAY['habit','capability','deficit','goal']::text[], ARRAY['routine_moment','control_level','time_limit','comfort_level','reason']::text[], 'water_dishwashing_flow_protocol', 'Fluxo de louça sem torneira aberta', 'Hoje, teste uma ordem de louça com ensaboar, pausar torneira e enxaguar por lote, mantendo higiene e conforto.', 'Aprofunda economia de água com método claro e repetível.', 7, 7, 'protocol'),
    ('water.shared_bathroom_notice', 'water', 'reduzir desperdício de água em espaço compartilhado', 4, 4, 'free', 20, 35, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','control_level','social_context','time_limit','reason']::text[], 'water_shared_bathroom_notice', 'Combinado leve do banheiro', 'Hoje, crie um lembrete discreto para um ponto de água compartilhado, como torneira, descarga ou chuveiro, sem expor ninguém.', 'Leva a missão para o ambiente real e compartilhado sem virar cobrança pessoal.', 7, 7, 'shared'),
    ('water.fixture_priority_list', 'water', 'priorizar pontos de maior desperdício de água', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','control_level','baseline','time_limit','reason']::text[], 'water_fixture_priority_list', 'Lista de prioridade da água', 'Hoje, liste três pontos de uso de água e escolha qual merece atenção primeiro por frequência, vazão ou risco de vazamento.', 'Melhora a escolha da missão ao priorizar impacto em vez de agir no primeiro ponto visível.', 7, 7, 'prioritization'),
    ('water.weekly_water_budget', 'water', 'reduzir consumo de água com orçamento semanal de rotina', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','control_level','baseline','time_limit','reason']::text[], 'water_weekly_budget', 'Orçamento semanal de água', 'Nesta semana, escolha duas rotinas com água e defina um limite observável para cada uma, acompanhando se o ajuste foi viável.', 'Cria acompanhamento maduro de consumo sem depender de equipamento novo.', 10, 9, 'system'),
    ('water.hidden_leak_investigation', 'water', 'evitar perda de água por vazamento oculto', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','safety_boundary','control_level','baseline','reason']::text[], 'water_hidden_leak_investigation', 'Investigação de vazamento oculto', 'Nesta semana, acompanhe sinais de vazamento como ruído, piso úmido ou consumo incomum e defina uma próxima ação segura.', 'Aumenta impacto ao buscar desperdício contínuo que normalmente passa despercebido.', 10, 9, 'investigation'),
    ('water.rain_event_storage_protocol', 'water', 'reaproveitar água de chuva sem risco sanitário', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['weather_condition','available_space','safety_boundary','control_level','reason']::text[], 'water_rain_event_storage_protocol', 'Protocolo seguro de chuva', 'Nesta semana, se chover, planeje uma coleta pequena e segura de água para limpeza externa ou planta, sem armazenar para consumo.', 'Traz maturidade ao reaproveitamento de água com limite sanitário explícito.', 10, 9, 'protocol'),
    ('water.household_water_rule_card', 'water', 'criar regra doméstica durável para economizar água', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['social_context','control_level','comfort_level','time_limit','reason']::text[], 'water_household_rule_card', 'Regra doméstica da água', 'Nesta semana, crie uma regra simples para um uso recorrente de água e combine como ela será lembrada sem gerar atrito.', 'Transforma ação isolada em sistema leve e repetível.', 10, 9, 'system'),

    ('energy.charging_station_review', 'energy', 'reduzir consumo invisível em carregadores e eletrônicos', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['device_or_room','safety_boundary','time_limit','reason']::text[], 'energy_charging_station_review', 'Revisão dos carregadores', 'Hoje, verifique carregadores e eletrônicos de um ponto da casa e escolha quais podem ser retirados da tomada com segurança.', 'Reduz energia invisível com uma decisão concreta sobre aparelhos reais.', 4, 5, 'audit'),
    ('energy.natural_light_workblock', 'energy', 'economizar energia aproveitando luz natural', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['device_or_room','routine_moment','comfort_level','time_limit','reason']::text[], 'energy_natural_light_workblock', 'Bloco com luz natural', 'Hoje, escolha uma tarefa curta e teste fazê-la perto de luz natural antes de acender lâmpada, se houver conforto visual.', 'Ajusta energia a um momento real de rotina sem sacrificar conforto.', 4, 5, 'timing'),
    ('energy.fridge_temperature_check', 'energy', 'evitar desperdício de energia na geladeira', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['device_or_room','safety_boundary','time_limit','reason']::text[], 'energy_fridge_temperature_check', 'Checagem da geladeira', 'Hoje, observe vedação, abertura frequente ou regulagem da geladeira e escolha um ajuste seguro para reduzir esforço do aparelho.', 'Atua em um equipamento de alto uso com limite de segurança alimentar.', 4, 5, 'audit'),
    ('energy.laundry_drying_choice', 'energy', 'reduzir energia em secagem de roupas', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['routine_moment','weather_condition','comfort_level','time_limit','reason']::text[], 'energy_laundry_drying_choice', 'Secagem com menos energia', 'Hoje, para uma próxima lavagem, compare se alguma peça pode secar naturalmente sem risco de mofo, atraso ou desconforto.', 'Economiza energia ao planejar secagem antes de usar equipamento.', 4, 5, 'planning'),
    ('energy.room_by_room_energy_map', 'energy', 'mapear pontos de maior consumo de energia', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['device_or_room','baseline','time_limit','reason']::text[], 'energy_room_by_room_map', 'Mapa de energia por cômodo', 'Hoje, liste os aparelhos mais usados em dois cômodos e escolha um ponto para reduzir tempo ligado ou stand-by.', 'Prioriza energia por ambiente e evita missão solta sem diagnóstico.', 7, 7, 'baseline'),
    ('energy.high_use_device_protocol', 'energy', 'reduzir consumo de aparelho de alto uso', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['device_or_room','safety_boundary','comfort_level','time_limit','reason']::text[], 'energy_high_use_device_protocol', 'Protocolo do aparelho crítico', 'Hoje, escolha um aparelho de uso intenso e defina uma regra segura de uso, pausa ou desligamento para a próxima semana.', 'Foca energia onde há maior repetição e cria regra testável.', 7, 7, 'protocol'),
    ('energy.cooling_heating_threshold', 'energy', 'reduzir energia em conforto térmico com limite seguro', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['device_or_room','comfort_level','weather_condition','safety_boundary','reason']::text[], 'energy_cooling_heating_threshold', 'Limite de conforto térmico', 'Hoje, defina um critério seguro para ligar ventilador, ar ou aquecedor, testando primeiro ventilação, sombra ou ajuste de roupa.', 'Evita consumo automático sem ignorar saúde, clima ou conforto básico.', 7, 7, 'threshold'),
    ('energy.shared_device_schedule', 'energy', 'otimizar energia em aparelho compartilhado', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['device_or_room','social_context','comfort_level','time_limit','reason']::text[], 'energy_shared_device_schedule', 'Agenda de aparelho compartilhado', 'Hoje, organize um uso combinado de aparelho compartilhado, como máquina ou forno, para reduzir ciclos separados quando for viável.', 'Melhora eficiência por coordenação, sem exigir que todos mudem a rotina inteira.', 7, 7, 'shared'),
    ('energy.weekly_peak_shift_plan', 'energy', 'reduzir energia em horários de maior demanda', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['time_window','device_or_room','comfort_level','safety_boundary','reason']::text[], 'energy_weekly_peak_shift_plan', 'Plano semanal fora do pico', 'Nesta semana, escolha dois usos elétricos flexíveis e teste deslocar horário quando isso não atrapalhar segurança, sono ou conforto.', 'Eleva a missão para planejamento energético com repetição controlada.', 10, 9, 'system'),
    ('energy.energy_bill_signal_review', 'energy', 'entender sinais de consumo de energia para reduzir desperdício', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['baseline','device_or_room','time_limit','reason']::text[], 'energy_bill_signal_review', 'Sinais da conta de energia', 'Nesta semana, revise um dado disponível de consumo de energia e conecte uma variação a um hábito ou aparelho provável.', 'Cria aprendizado maduro a partir de evidência, não só de intenção.', 10, 9, 'baseline'),
    ('energy.seasonal_comfort_protocol', 'energy', 'criar protocolo sazonal de economia de energia', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['weather_condition','comfort_level','device_or_room','time_limit','reason']::text[], 'energy_seasonal_comfort_protocol', 'Protocolo sazonal de conforto', 'Nesta semana, monte uma ordem de ações antes de ligar climatização, começando por sombra, ventilação, roupa ou horário adequado.', 'Transforma conforto térmico em sistema de decisão seguro e sustentável.', 10, 9, 'protocol'),
    ('energy.family_energy_agreement', 'energy', 'reduzir consumo de energia em rotina compartilhada', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['social_context','device_or_room','comfort_level','time_limit','reason']::text[], 'energy_family_energy_agreement', 'Acordo de energia da casa', 'Nesta semana, proponha um acordo leve para um aparelho ou cômodo compartilhado, com uma regra simples e fácil de lembrar.', 'Cria mudança durável quando o consumo depende de mais de uma pessoa.', 10, 9, 'shared'),

    ('waste.packaging_source_audit', 'waste', 'reduzir resíduos identificando origem de embalagens', 3, 3, 'free', 10, 20, ARRAY['habit','capability','deficit','goal']::text[], ARRAY['material_type','purchase_context','time_limit','reason']::text[], 'waste_packaging_source_audit', 'Origem das embalagens', 'Hoje, observe três embalagens descartadas e identifique de onde vieram para escolher uma fonte de redução futura.', 'Ataca o resíduo antes da lixeira, conectando descarte a decisão de compra ou pedido.', 4, 5, 'audit'),
    ('waste.reusable_container_station', 'waste', 'evitar descarte com recipiente reutilizável disponível', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['available_space','reuse_option','time_limit','reason']::text[], 'waste_reusable_container_station', 'Estação de recipiente reutilizável', 'Hoje, organize um recipiente reutilizável em um lugar visível para substituir um descarte recorrente.', 'Reduz resíduo por disponibilidade prática, não por cobrança abstrata.', 4, 5, 'setup'),
    ('waste.paper_digital_switch', 'waste', 'diminuir resíduos de papel evitáveis', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['material_type','control_level','time_limit','reason']::text[], 'waste_paper_digital_switch', 'Troca de papel evitável', 'Hoje, escolha um uso recorrente de papel e teste uma alternativa digital ou reutilizável que não atrapalhe sua organização.', 'Remove um fluxo pequeno e repetido de resíduo sem impor sistema complexo.', 4, 5, 'substitution'),
    ('waste.organic_storage_trial', 'waste', 'reduzir descarte orgânico por armazenamento correto', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['material_type','storage_context','time_limit','reason']::text[], 'waste_organic_storage_trial', 'Teste de orgânicos separados', 'Hoje, separe por algumas horas um resíduo orgânico seguro e observe se há forma limpa de reduzir cheiro, volume ou mistura.', 'Cria aprendizado sobre orgânicos sem exigir compostagem completa.', 4, 5, 'trial'),
    ('waste.special_waste_batch', 'waste', 'encaminhar resíduos especiais para destino correto', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['collection_access','material_type','available_space','time_limit','reason']::text[], 'waste_special_waste_batch', 'Lote de resíduo especial', 'Hoje, reúna pilhas, eletrônicos pequenos, óleo ou remédios vencidos em um lote seguro e defina o destino correto possível.', 'Aumenta impacto ao separar resíduos que não deveriam ir ao lixo comum.', 7, 7, 'batch'),
    ('waste.room_by_room_discard_scan', 'waste', 'reduzir descarte por diagnóstico de cômodos', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['available_space','material_type','time_limit','reason']::text[], 'waste_room_scan', 'Varredura de descarte por cômodo', 'Hoje, escolha dois cômodos e liste um resíduo recorrente de cada um para atacar a origem primeiro.', 'Cria visão sistêmica do lixo em vez de tratar só uma embalagem isolada.', 7, 7, 'baseline'),
    ('waste.low_waste_purchase_filter', 'waste', 'evitar resíduos antes da compra', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','material_type','budget_limit','reason']::text[], 'waste_low_waste_purchase_filter', 'Filtro de compra com menos lixo', 'Hoje, antes de uma compra ou pedido, compare opções por quantidade de embalagem, durabilidade e destino depois do uso.', 'Leva a redução de resíduos para a decisão anterior ao descarte.', 7, 7, 'decision'),
    ('waste.repair_candidate_triage', 'waste', 'reduzir descarte por triagem de reparo', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['reuse_option','available_space','budget_limit','time_limit','reason']::text[], 'waste_repair_candidate_triage', 'Triagem de reparo antes do descarte', 'Hoje, escolha um item que poderia virar lixo e defina se vale reparar, doar, reaproveitar ou encaminhar corretamente.', 'Evita descarte automático com decisão estruturada e realista.', 7, 7, 'triage'),
    ('waste.weekly_bin_weight_estimate', 'waste', 'acompanhar volume de resíduos para reduzir geração', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['baseline','material_type','time_limit','reason']::text[], 'waste_weekly_bin_estimate', 'Estimativa semanal do lixo', 'Nesta semana, estime o volume ou peso de uma lixeira em dois momentos e escolha uma origem para reduzir primeiro.', 'Cria linha de base para resíduos e melhora a precisão das próximas missões.', 10, 9, 'baseline'),
    ('waste.collection_calendar_system', 'waste', 'melhorar reciclagem com calendário de coleta', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['collection_access','material_type','available_space','reason']::text[], 'waste_collection_calendar_system', 'Sistema de calendário de coleta', 'Nesta semana, monte um lembrete simples para coleta, ecoponto ou entrega de material e separe um item real para testar.', 'Transforma separação de resíduos em sistema durável.', 10, 9, 'system'),
    ('waste.zero_waste_event_plan', 'waste', 'evitar resíduos em evento ou encontro pequeno', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['social_context','material_type','reuse_option','budget_limit','reason']::text[], 'waste_zero_waste_event_plan', 'Plano de encontro com menos lixo', 'Nesta semana, planeje um encontro, lanche ou saída pequena com um item reutilizável e um descarte evitado.', 'Aplica redução de resíduos em contexto social sem exigir perfeição.', 10, 9, 'planning'),
    ('waste.shared_waste_rule', 'waste', 'criar regra compartilhada para reduzir descarte', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['social_context','available_space','collection_access','time_limit','reason']::text[], 'waste_shared_rule', 'Regra compartilhada do lixo', 'Nesta semana, combine uma regra simples para um resíduo recorrente em casa, trabalho ou estudo, com local e destino definidos.', 'Cria coordenação onde o descarte depende de mais de uma pessoa.', 10, 9, 'shared'),

    ('transport.trip_chain_check', 'transport', 'reduzir emissões combinando deslocamentos', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','time_window','safety_condition','reason']::text[], 'transport_trip_chain_check', 'Checagem de deslocamentos combinados', 'Hoje, escolha duas tarefas fora de casa e compare se podem virar uma única saída segura.', 'Reduz viagens extras com planejamento simples de rota.', 4, 5, 'planning'),
    ('transport.remote_option_review', 'transport', 'evitar deslocamento quando uma alternativa remota resolve', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','control_level','time_limit','reason']::text[], 'transport_remote_option_review', 'Opção remota antes do trajeto', 'Hoje, escolha um deslocamento previsto e verifique se parte dele pode ser resolvida por mensagem, ligação ou serviço online.', 'Evita emissão sem comprometer compromisso importante.', 4, 5, 'substitution'),
    ('transport.off_peak_errand_check', 'transport', 'reduzir tempo parado e emissões em deslocamento', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','time_window','safety_condition','reason']::text[], 'transport_off_peak_errand', 'Horário com menos espera', 'Hoje, compare se uma tarefa recorrente pode ser feita em horário de menor fila, trânsito ou espera, mantendo segurança.', 'Reduz emissões indiretas ao evitar tempo parado e deslocamento ineficiente.', 4, 5, 'timing'),
    ('transport.active_segment_trial', 'transport', 'substituir pequeno trecho motorizado com segurança', 3, 3, 'free', 10, 25, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','mobility_limit','safety_condition','time_limit','reason']::text[], 'transport_active_segment_trial', 'Trecho ativo seguro', 'Hoje, identifique um trecho curto que poderia ser feito a pé ou de bicicleta, apenas se clima, segurança e mobilidade permitirem.', 'Testa mobilidade ativa como trecho pequeno e realista.', 4, 5, 'trial'),
    ('transport.weekly_commute_baseline', 'transport', 'entender emissões de deslocamento recorrente', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','baseline','time_window','reason']::text[], 'transport_weekly_commute_baseline', 'Linha de base do deslocamento', 'Hoje, registre um deslocamento recorrente com distância aproximada, modo usado e uma alternativa possível para testar depois.', 'Cria diagnóstico para transporte antes de cobrar mudança maior.', 7, 7, 'baseline'),
    ('transport.public_transport_buffer_plan', 'transport', 'viabilizar transporte coletivo com menor atrito', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','safety_condition','time_window','mobility_limit','reason']::text[], 'transport_public_buffer_plan', 'Plano com margem para transporte coletivo', 'Hoje, escolha uma rota possível de transporte coletivo e calcule uma margem de tempo realista para não transformar a opção em estresse.', 'Torna alternativa de menor emissão mais viável e segura.', 7, 7, 'planning'),
    ('transport.carpool_candidate_review', 'transport', 'reduzir emissões com compartilhamento seguro de trajeto', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','social_context','safety_condition','time_window','reason']::text[], 'transport_carpool_candidate_review', 'Candidato a trajeto compartilhado', 'Hoje, identifique um deslocamento em que compartilhar rota seria seguro e viável, sem compromisso de executar agora.', 'Abre opção de menor emissão sem forçar exposição ou risco.', 7, 7, 'social'),
    ('transport.delivery_pickup_choice', 'transport', 'reduzir deslocamentos ou entregas desnecessárias', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','purchase_context','time_window','safety_condition','reason']::text[], 'transport_delivery_pickup_choice', 'Entrega ou retirada consciente', 'Hoje, antes de pedir entrega ou sair para retirar algo, compare se é possível agrupar com outra rota segura.', 'Conecta transporte a consumo, reduzindo viagem isolada.', 7, 7, 'decision'),
    ('transport.monthly_mobility_budget', 'transport', 'planejar menos emissões de transporte no mês', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','baseline','time_window','safety_condition','reason']::text[], 'transport_monthly_mobility_budget', 'Orçamento mensal de mobilidade', 'Nesta semana, escolha três deslocamentos frequentes e defina qual pode ter menos emissões neste mês sem perder segurança.', 'Leva transporte para planejamento maduro e recorrente.', 10, 9, 'system'),
    ('transport.multi_stop_route_system', 'transport', 'reduzir emissões por sistema de rotas combinadas', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','time_window','safety_condition','reason']::text[], 'transport_multi_stop_route_system', 'Sistema de rotas combinadas', 'Nesta semana, monte uma regra para agrupar tarefas externas por região, dia ou prioridade, evitando saídas avulsas.', 'Transforma economia de transporte em sistema reutilizável.', 10, 9, 'system'),
    ('transport.low_carbon_backup_plan', 'transport', 'manter alternativa de baixo carbono quando a rotina muda', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','mobility_limit','safety_condition','time_window','reason']::text[], 'transport_low_carbon_backup_plan', 'Plano B de baixo carbono', 'Nesta semana, defina uma alternativa segura para quando a rota habitual falhar, como resolver remoto, compartilhar ou adiar sem viagem extra.', 'Aumenta resiliência da mudança sem depender de uma única rota perfeita.', 10, 9, 'resilience'),
    ('transport.household_transport_agreement', 'transport', 'reduzir emissões em deslocamentos compartilhados', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['route_type','social_context','safety_condition','time_window','reason']::text[], 'transport_household_agreement', 'Acordo de deslocamento compartilhado', 'Nesta semana, combine uma regra leve para agrupar caronas, compras ou tarefas externas com alguém da rotina.', 'Cria redução de emissões quando o deslocamento envolve mais de uma pessoa.', 10, 9, 'shared'),

    ('food.first_expiry_box', 'food', 'evitar desperdício alimentar priorizando vencimento', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','storage_context','diet_boundary','time_limit','reason']::text[], 'food_first_expiry_box', 'Caixa de usar primeiro', 'Hoje, escolha um espaço da geladeira ou despensa para itens que precisam ser usados primeiro, sem impor mudança alimentar.', 'Reduz desperdício com visibilidade e prioridade concreta.', 4, 5, 'setup'),
    ('food.portion_leftover_plan', 'food', 'diminuir desperdício por ajuste de porção e sobra', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','storage_context','diet_boundary','time_limit','reason']::text[], 'food_portion_leftover_plan', 'Plano de sobra segura', 'Hoje, antes de uma refeição, defina como guardar uma sobra segura ou ajustar porção para evitar descarte.', 'Atua no desperdício alimentar antes que ele aconteça.', 4, 5, 'planning'),
    ('food.pantry_duplicate_check', 'food', 'evitar compra duplicada e desperdício alimentar', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','storage_context','budget_limit','time_limit','reason']::text[], 'food_pantry_duplicate_check', 'Checagem de duplicados', 'Hoje, verifique um grupo de alimentos da despensa e anote o que não precisa ser comprado de novo agora.', 'Reduz desperdício e gasto por compra repetida.', 4, 5, 'audit'),
    ('food.low_waste_ordering_choice', 'food', 'reduzir resíduos e desperdício ao pedir comida', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','diet_boundary','budget_limit','time_limit','reason']::text[], 'food_low_waste_ordering_choice', 'Pedido com menos desperdício', 'Hoje, se pedir comida, escolha porção, embalagem ou extras de forma a reduzir sobra e descarte desnecessário.', 'Melhora uma decisão alimentar real sem impor dieta.', 4, 5, 'decision'),
    ('food.weekly_menu_rescue_plan', 'food', 'reduzir desperdício alimentar com planejamento semanal', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','storage_context','diet_boundary','time_limit','reason']::text[], 'food_weekly_menu_rescue_plan', 'Menu de resgate da semana', 'Hoje, liste dois alimentos com risco de estragar e escolha uma refeição da semana para usar cada um.', 'Cria ponte entre inventário e refeição real.', 7, 7, 'planning'),
    ('food.freezer_label_system', 'food', 'evitar desperdício por armazenamento rastreável', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','storage_context','time_limit','reason']::text[], 'food_freezer_label_system', 'Etiqueta simples no congelador', 'Hoje, organize um item congelado ou guardado com nome e data aproximada para evitar esquecimento e descarte.', 'Transforma armazenamento em sistema visível de prevenção.', 7, 7, 'system'),
    ('food.plant_protein_trial', 'food', 'reduzir pegada ambiental de uma refeição com alternativa vegetal', 4, 4, 'free', 20, 40, ARRAY['habit','capability','preference','goal']::text[], ARRAY['kitchen_access','diet_boundary','budget_limit','time_limit','reason']::text[], 'food_plant_protein_trial', 'Teste de proteína vegetal', 'Hoje, escolha uma refeição em que uma proteína vegetal já disponível possa substituir parte de maior impacto, respeitando gosto e saúde.', 'Aumenta ambição alimentar sem impor mudança incompatível.', 7, 7, 'trial'),
    ('food.shopping_list_gap_review', 'food', 'evitar desperdício alimentar pela lista de compras', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','kitchen_access','storage_context','budget_limit','reason']::text[], 'food_shopping_list_gap_review', 'Lista contra desperdício', 'Hoje, revise uma lista de compras e remova ou ajuste um item que não tem plano claro de uso.', 'Reduz desperdício ao ligar compra a armazenamento e refeição.', 7, 7, 'decision'),
    ('food.food_waste_tracking_week', 'food', 'medir desperdício alimentar para reduzir repetição', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','storage_context','baseline','time_limit','reason']::text[], 'food_waste_tracking_week', 'Rastreamento semanal de desperdício', 'Nesta semana, registre todo alimento descartado ou quase descartado e escolha uma causa para prevenir primeiro.', 'Cria aprendizado maduro com dados reais da cozinha.', 10, 9, 'baseline'),
    ('food.shared_kitchen_rule', 'food', 'reduzir desperdício alimentar em cozinha compartilhada', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','social_context','storage_context','diet_boundary','reason']::text[], 'food_shared_kitchen_rule', 'Regra da cozinha compartilhada', 'Nesta semana, combine uma regra simples para sobras, prazos ou itens abertos em uma cozinha compartilhada.', 'Atua onde desperdício depende de coordenação entre pessoas.', 10, 9, 'shared'),
    ('food.seasonal_purchase_protocol', 'food', 'reduzir impacto alimentar com compra sazonal e planejada', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','budget_limit','diet_boundary','storage_context','reason']::text[], 'food_seasonal_purchase_protocol', 'Protocolo de compra sazonal', 'Nesta semana, escolha um alimento de compra recorrente e compare uma opção mais sazonal, local ou de menor desperdício.', 'Eleva a escolha alimentar sem impor dieta ou gasto novo.', 10, 9, 'decision'),
    ('food.meal_prep_energy_water_check', 'food', 'reduzir água, energia e desperdício no preparo de comida', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['kitchen_access','storage_context','time_limit','diet_boundary','reason']::text[], 'food_meal_prep_energy_water_check', 'Preparo com menos água e energia', 'Nesta semana, planeje um preparo que aproveite panela, forno, água ou sobra de forma mais eficiente, mantendo segurança alimentar.', 'Conecta alimentação, energia e água em uma ação madura de cozinha.', 10, 9, 'system'),

    ('consumption.borrow_list_check', 'consumption', 'evitar compra por empréstimo ou compartilhamento', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','reuse_option','budget_limit','time_limit','reason']::text[], 'consumption_borrow_list_check', 'Lista do que pode ser emprestado', 'Hoje, escolha uma necessidade não urgente e liste uma pessoa, lugar ou alternativa segura para pegar emprestado antes de comprar.', 'Reduz consumo criando opção concreta antes da compra.', 4, 5, 'decision'),
    ('consumption.warranty_repair_lookup', 'consumption', 'prolongar vida útil por reparo ou garantia', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','reuse_option','budget_limit','time_limit','reason']::text[], 'consumption_warranty_repair_lookup', 'Checagem de reparo ou garantia', 'Hoje, verifique se um item parado ainda tem garantia, peça simples de reposição ou caminho de reparo viável.', 'Evita troca prematura e transforma dúvida em próxima ação.', 4, 5, 'repair'),
    ('consumption.owned_item_substitute', 'consumption', 'reduzir compra usando item já existente', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','reuse_option','available_space','time_limit','reason']::text[], 'consumption_owned_item_substitute', 'Substituto que já existe', 'Hoje, antes de comprar algo pequeno, escolha um item que você já tem e teste se ele resolve a mesma necessidade.', 'Reduz consumo por substituição prática, não por privação.', 4, 5, 'substitution'),
    ('consumption.digital_subscription_audit', 'consumption', 'diminuir consumo recorrente invisível', 3, 3, 'free', 10, 20, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','budget_limit','time_limit','reason']::text[], 'consumption_subscription_audit', 'Auditoria de assinatura esquecida', 'Hoje, verifique uma assinatura, app ou serviço recorrente e decida se ainda tem uso real antes da próxima cobrança.', 'Ataca consumo invisível e recorrente com uma decisão simples.', 4, 5, 'audit'),
    ('consumption.purchase_delay_protocol', 'consumption', 'evitar compra por impulso com pausa estruturada', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','delay_window','budget_limit','reason']::text[], 'consumption_purchase_delay_protocol', 'Protocolo de espera antes da compra', 'Hoje, crie uma regra de espera para compras não urgentes, com prazo, motivo e alternativa de uso do que já existe.', 'Transforma impulso de consumo em decisão revisável.', 7, 7, 'protocol'),
    ('consumption.care_routine_for_item', 'consumption', 'prolongar vida útil por cuidado preventivo', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['reuse_option','time_limit','budget_limit','reason']::text[], 'consumption_care_routine_for_item', 'Rotina de cuidado de um item', 'Hoje, escolha um item usado com frequência e defina uma rotina de limpeza, ajuste ou armazenamento para durar mais.', 'Reduz descarte futuro com manutenção preventiva.', 7, 7, 'maintenance'),
    ('consumption.shared_library_map', 'consumption', 'reduzir compras por rede de compartilhamento', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['reuse_option','social_context','budget_limit','time_limit','reason']::text[], 'consumption_shared_library_map', 'Mapa de compartilhamento', 'Hoje, monte um pequeno mapa de itens que podem ser emprestados, alugados, compartilhados ou consultados antes de comprar.', 'Cria infraestrutura social para consumir menos.', 7, 7, 'shared'),
    ('consumption.material_choice_review', 'consumption', 'reduzir impacto de compra por durabilidade e reparo', 4, 4, 'free', 20, 40, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','reuse_option','budget_limit','reason']::text[], 'consumption_material_choice_review', 'Critério de material durável', 'Hoje, para uma compra futura, compare durabilidade, reparo e descarte de duas opções antes de decidir.', 'Melhora qualidade da decisão quando comprar não puder ser evitado.', 7, 7, 'decision'),
    ('consumption.monthly_needs_budget', 'consumption', 'reduzir consumo planejando necessidades reais', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','budget_limit','delay_window','reason']::text[], 'consumption_monthly_needs_budget', 'Orçamento de necessidades reais', 'Nesta semana, liste compras desejadas do mês e separe necessidade real, manutenção, empréstimo possível e impulso de espera.', 'Cria camada madura de planejamento contra consumo automático.', 10, 9, 'system'),
    ('consumption.household_reuse_system', 'consumption', 'reduzir compras e descarte com sistema doméstico de reuso', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['reuse_option','available_space','social_context','budget_limit','reason']::text[], 'consumption_household_reuse_system', 'Sistema doméstico de reuso', 'Nesta semana, crie um local ou regra para itens que podem ser reutilizados, compartilhados ou doados antes de compra nova.', 'Transforma reuso em sistema visível e contínuo.', 10, 9, 'system'),
    ('consumption.repair_network_map', 'consumption', 'reduzir descarte com rede de reparo viável', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['reuse_option','budget_limit','social_context','time_limit','reason']::text[], 'consumption_repair_network_map', 'Mapa de reparo possível', 'Nesta semana, identifique duas opções de reparo, troca de peça, tutorial seguro ou ajuda local para um item importante.', 'Aumenta maturidade de consumo ao criar caminho real de reparo.', 10, 9, 'repair'),
    ('consumption.purchase_criteria_card', 'consumption', 'criar critério durável para consumo consciente', 5, 5, 'free', 30, 60, ARRAY['habit','capability','context','goal']::text[], ARRAY['purchase_context','delay_window','budget_limit','reuse_option','reason']::text[], 'consumption_purchase_criteria_card', 'Cartão de critério de compra', 'Nesta semana, escreva um critério simples para compras futuras: necessidade, uso previsto, alternativa existente, reparo e descarte.', 'Cria um filtro reutilizável para decisões de consumo.', 10, 9, 'system')
)
INSERT INTO public.mission_patterns (
  key,
  category,
  environmental_goal,
  difficulty_min,
  difficulty_max,
  cost_level,
  effort_minutes_min,
  effort_minutes_max,
  required_or_helpful_fact_types,
  disqualifying_fact_keys,
  personalization_slots,
  impact_model_key,
  action_fingerprint,
  recurrence_allowed,
  fallback_title_pt,
  fallback_description_pt,
  fallback_reason_pt,
  metadata,
  active
)
SELECT
  key,
  category,
  environmental_goal,
  difficulty_min,
  difficulty_max,
  cost_level,
  effort_minutes_min,
  effort_minutes_max,
  required_or_helpful_fact_types,
  ARRAY[]::text[],
  personalization_slots,
  impact_model_key,
  key,
  false,
  fallback_title_pt,
  fallback_description_pt,
  fallback_reason_pt,
  jsonb_build_object(
    'seed_version', 'mission_quality_blueprints_v2',
    'algorithm', 'deterministic_mission_patterns_v3',
    'difficulty_bucket', difficulty_min,
    'cooldown_days', cooldown_days,
    'target_user_level', target_user_level,
    'maturity_stage', maturity_stage,
    'additive_quality_pattern', true,
    'quality_blueprint_v2', true
  ),
  true
FROM new_patterns
ON CONFLICT (key) DO UPDATE SET
  category = EXCLUDED.category,
  environmental_goal = EXCLUDED.environmental_goal,
  difficulty_min = EXCLUDED.difficulty_min,
  difficulty_max = EXCLUDED.difficulty_max,
  cost_level = EXCLUDED.cost_level,
  effort_minutes_min = EXCLUDED.effort_minutes_min,
  effort_minutes_max = EXCLUDED.effort_minutes_max,
  required_or_helpful_fact_types = EXCLUDED.required_or_helpful_fact_types,
  personalization_slots = EXCLUDED.personalization_slots,
  impact_model_key = EXCLUDED.impact_model_key,
  action_fingerprint = EXCLUDED.action_fingerprint,
  recurrence_allowed = EXCLUDED.recurrence_allowed,
  fallback_title_pt = EXCLUDED.fallback_title_pt,
  fallback_description_pt = EXCLUDED.fallback_description_pt,
  fallback_reason_pt = EXCLUDED.fallback_reason_pt,
  metadata = COALESCE(public.mission_patterns.metadata, '{}'::jsonb) || EXCLUDED.metadata,
  active = true,
  updated_at = now();

COMMIT;
